/**
 * Seed data — pure data, with no dependency on Prisma.
 *
 * IMPORTANT NOTES
 * 1) The stories rest on real events and each carries the source it is based on
 *    in its `sourceUrl` field. Never leave that field empty when adding a story.
 * 2) The editor records in `authors` are placeholders; replace them with your own.
 * 3) Cover images are indicative. If you use a copyrighted news photograph, fill
 *    in the `imageCredit` field.
 */

export type SeedCategory = { name: string; slug: string; description: string; order: number };
export type SeedTag = { name: string; slug: string };
export type SeedAuthor = { name: string; slug: string; avatar: string; bio: string };

export type SeedPhilosopher = {
  name: string;
  slug: string;
  headline: string;
  bio: string;
  avatar: string | null;
  country: string;
  birthYear: number | null;
  affiliation: string | null;
  website: string | null;
  /** Show in the "Philosophers We Follow" strip on the home page? */
  featured: boolean;
  /**
   * APPROVAL LIST — a required field.
   *
   * `true`  → appears in the Directory and in the "Philosophers We Follow" strip.
   * `false` → appears in no list. The record is not deleted, only hidden, so old
   *           links and story credits are not broken.
   *
   * This field is not optional: an explicit decision is required for every name,
   * which is what stops names being added at random.
   */
  listed: boolean;

  /* --- Directory fields (all optional) ---
     Leave a field empty when unsure; never invent information. */
  fullName?: string;
  /** Free-form, e.g. "1953", "c. 470 BC". */
  birthDate?: string;
  /** Not written for living philosophers. */
  deathDate?: string;
  /** Defaults to true; false for philosophers who have died. */
  alive?: boolean;
  period?: string;
  school?: string;
  /** Comma-separated areas of work. */
  areas?: string;
  /** One work per line. */
  majorWorks?: string;
  /** Comma-separated key concepts. */
  keyConcepts?: string;
  influencedBy?: string;
  influenced?: string;
  /** Long-form biography (Markdown). */
  longBio?: string;
  /** "Title — URL" on each line. */
  sources?: string;
};

/** One of the sources a story rests on (rules 6 and 26). */
export type SeedSource = {
  title: string;
  publisher?: string;
  /** Free-form: "12 August 2026". */
  date?: string;
  url: string;
  /** The primary source is shown first in the credit. */
  primary?: boolean;
};

/** A conference, symposium, seminar, webinar, workshop or call for papers. */
export type SeedEvent = {
  title: string;
  slug: string;
  summary?: string;
  /** Markdown. */
  description?: string;
  /** CONFERENCE | CONGRESS | SYMPOSIUM | WORKSHOP | SEMINAR | WEBINAR | PANEL | LECTURE | COLLOQUIUM | SUMMER_SCHOOL | WINTER_SCHOOL | CFP */
  kind?: string;
  speakers?: string;
  organizer?: string;
  topic?: string;
  /** ONLINE | IN_PERSON | HYBRID */
  format?: string;
  /** ISO 8601. When no time is known, write the start of the day and leave hasTime false. */
  startsAt: string;
  endsAt?: string;
  timezone?: string;
  hasTime?: boolean;
  city?: string;
  country?: string;
  venue?: string;
  registrationUrl?: string;
  fee?: string;
  deadline?: string;
  cfpDeadline?: string;
  website?: string;
  sourceName?: string;
  sourceUrl?: string;
  coverImage?: string;
  featured?: boolean;
  publishedAt?: string | null;
};

export type SeedBook = {
  title: string;
  slug: string;
  originalTitle: string | null;
  publisher: string | null;
  translator: string | null;
  language: string;
  isbn: string | null;
  coverImage: string | null;
  description: string;
  year: number | null;
  link: string | null;
  philosopherSlug: string | null;
  /** Slug of the story announcing the book, if there is one. */
  postSlug: string | null;
};

export type SeedPost = {
  title: string;
  slug: string;
  summary: string;
  content: string;
  /** SEO title — falls back to `title` when empty. */
  seoTitle?: string;
  /** Search-result description — falls back to `summary` when empty. */
  metaDescription?: string;
  /** NEWS | ANALYSIS | PROFILE | BOOK | INTERVIEW | EVENT | HISTORY | CONCEPT */
  contentType?: string;
  coverImage: string;
  imageCredit: string | null;
  featured: boolean;
  sourceName: string | null;
  sourceUrl: string | null;
  /** ISO 8601; null saves the story as a draft. */
  publishedAt: string | null;
  authorSlug: string;
  categorySlug: string;
  tagSlugs: string[];
  philosopherSlugs: string[];
  /** Further sources. `sourceName`/`sourceUrl` is the main one; all are listed here. */
  sources?: SeedSource[];
};

