    featured: false,
    sourceName: "Irish Philosophy",
    sourceUrl: "https://www.irishphilosophy.com/2021/09/02/william-rowan-hamilton-and-kant/",
    publishedAt: "2026-09-02T03:40:00.000Z",
    authorSlug: "newsroom",
    categorySlug: "this-day-in-philosophy",
    tagSlugs: ["history", "kant", "philosophy-of-science", "political-philosophy", "critical-theory"],
